css:
/* Owner-approved SDCE print design (2026-11-09): the standard Frappe print look. Colours are the Frappe v16
   print greys as literal hex (no CSS variables, @import or remote fonts: wkhtmltopdf's old Qt WebKit drops
   them): text #171717, secondary #525252, labels #7c7c7c, table header #f3f3f3, borders #d1d8dd, light
   separators #ededed, heading underline #aaa. Bundled app font plus the legacy .print-format override that
   lets the content own the full printable width. */
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Bold.ttf'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Bold.ttf'); font-weight: bold; font-style: normal; }

.print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
.print-format-gutter { padding: 0 !important; }

/* text-rendering auto: frappe's print bundle sets optimizeLegibility on body,
   which makes Qt draw RTL lines wider than it measures them (text crosses cell
   borders); resetting it here fixes the geometry. */
.emc { text-rendering: auto; font-family: 'Noto Sans Arabic', 'Card Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; font-size: 9pt; line-height: 1.4; color: #171717; width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.emc table { width: 100%; border-collapse: collapse; margin: 0; }
.emc th, .emc td { word-wrap: break-word; }
/* old Qt WebKit (wkhtmltopdf) follows CSS direction, not the dir attribute, and has no text-align: start */
.emc.rtl { direction: rtl; text-align: right; }
.emc.ltr { direction: ltr; text-align: left; }

.emc-lh { margin-bottom: 3mm; text-align: center; }
.emc-lh img { max-height: 22mm; max-width: 100%; }

.emc-co { font-size: 10pt; font-weight: bold; color: #525252; margin: 0 0 1px; }
.emc-title { border-bottom: 1px solid #aaa; margin: 0 0 2.5mm; padding-bottom: 3px; }
.emc-title h2 { margin: 0; font-size: 16pt; font-weight: bold; color: #171717; line-height: 1.3; }
.emc-title h2 .st { color: #7c7c7c; font-size: 11pt; }

/* no rowspan: Qt WebKit misplaces auto-layout columns next to a rowspan cell,
   so the image sits in its own cell of an outer wrapper table instead. */
.emc-head-outer { margin-bottom: 2.5mm !important; }
.emc-head-outer td.ehc { border: none !important; padding: 0 !important; vertical-align: top; }
.emc-meta { table-layout: fixed; }
.emc-meta td { border: none !important; padding: 0.6mm 1mm !important; vertical-align: top; color: #171717; }
.emc-meta td.ml { width: 13%; font-weight: bold; color: #7c7c7c; }
.emc.rtl .emc-meta td { text-align: right; }
.emc.ltr .emc-meta td { text-align: left; }
.emc-meta .nw { white-space: nowrap; }
.emc-img { width: 15%; border: 1px solid #d1d8dd !important; text-align: center; vertical-align: middle; padding: 1mm !important; }
.emc-img img { max-width: 100%; max-height: 24mm; }

.emc-days-wrap td.emc-half { width: 50%; vertical-align: top; padding: 0 0.8mm !important; border: none !important; }
.emc-days { table-layout: fixed; border: 1px solid #d1d8dd; }
.emc-days th, .emc-days td { border: 1px solid #d1d8dd !important; padding: 0 2px !important; text-align: center; vertical-align: middle; height: 5.4mm; font-size: 8pt; overflow: hidden; }
.emc-days th { background: #f3f3f3 !important; color: #525252; font-weight: bold; padding: 1mm 1px !important; font-size: 7.5pt; }
.emc.rtl .emc-days td.t { text-align: right; }
.emc.ltr .emc-days td.t { text-align: left; }
.emc-days td.c { direction: ltr; unicode-bidi: embed; white-space: nowrap; }
.emc-days td.num { direction: ltr; unicode-bidi: embed; white-space: nowrap; text-align: right; }
.emc-days tr.fri td { background: #fafafa !important; }
.emc-days tr.off td { color: #7c7c7c; }

/* the settlement block: additions/deductions rows at the start side, the totals right next to their
   amount column at the end side of the page, as in a standard invoice */
.emc-sum { margin-top: 3mm !important; table-layout: fixed; }
.emc-sum td.emc-sum-s { width: 40%; vertical-align: top; border: none !important; padding: 0 !important; }
.emc-sum td.emc-sum-g { width: 2%; border: none !important; padding: 0 !important; }
.emc-sum td.emc-sum-m, .emc-sum td.emc-sum-e { width: 28%; vertical-align: top; border: none !important; padding: 0 !important; }
.emc-cap { font-weight: bold; color: #525252; padding: 0 1mm 1mm; border-bottom: 1px solid #aaa; margin-bottom: 0; }

.emc-adj { table-layout: fixed; border: 1px solid #d1d8dd; }
.emc-adj th, .emc-adj td { border: 1px solid #d1d8dd !important; padding: 0.8mm 1mm !important; vertical-align: middle; font-size: 8pt; overflow: hidden; }
.emc-adj th { background: #f3f3f3 !important; color: #525252; font-weight: bold; text-align: center; }
.emc.rtl .emc-adj td { text-align: right; }
.emc.ltr .emc-adj td { text-align: left; }
.emc-adj td.c { text-align: center !important; }
.emc-adj td.num { direction: ltr; unicode-bidi: embed; white-space: nowrap; text-align: right !important; }

/* one weight per cell: Qt overlaps a regular+bold Arabic run pair */
.emc-tot { margin-bottom: 2.5mm !important; page-break-inside: avoid; }
.emc-tot th { color: #525252; font-weight: bold; padding: 0 1mm 1mm !important; border-bottom: 1px solid #aaa !important; }
.emc-tot td { padding: 0.7mm 1mm !important; border-bottom: 1px solid #ededed !important; vertical-align: middle; }
.emc-tot td.k { width: 58%; color: #525252; }
.emc-tot td.v { direction: ltr; unicode-bidi: embed; font-weight: bold; white-space: nowrap; }
.emc.rtl .emc-tot th, .emc.rtl .emc-tot td.k { text-align: right; }
.emc.ltr .emc-tot th, .emc.ltr .emc-tot td.k { text-align: left; }
.emc.rtl .emc-tot td.v { text-align: left; }
.emc.ltr .emc-tot td.v { text-align: right; }
.emc-tot tr.last td { font-size: 10pt; font-weight: bold; color: #171717; border-top: 1px solid #aaa !important; border-bottom: none !important; }

.emc-notes { margin-top: 2mm; padding: 1mm 0; border-top: 1px solid #ededed; }
.emc-notes .ml { font-weight: bold; color: #7c7c7c; }

.emc-sign { margin-top: 5mm !important; table-layout: fixed; page-break-inside: avoid; }
.emc-sign td { width: 33%; text-align: center !important; padding: 0 5mm !important; border: none !important; vertical-align: top; }
.emc-sign .l { border-top: 1px solid #999; margin: 9mm 8% 1.2mm; height: 0; }
.emc-sign .t { font-weight: bold; color: #525252; }
.emc-sign .n { color: #171717; min-height: 4mm; }

html:
{%- set days = doc.days or [] -%}
{%- set half = ((days|length) + 1) // 2 -%}
{%- set eq_type = frappe.db.get_value("Card Equipment", doc.equipment, "equipment_type") if doc.equipment else "" -%}
{%- set supplier_name = frappe.db.get_value("Supplier", doc.supplier, "supplier_name") if doc.supplier else "" -%}
{%- set customer_name = frappe.db.get_value("Customer", doc.customer, "customer_name") if doc.customer else "" -%}
{%- set company_name = (frappe.db.get_value("Company", doc.company, "company_name") or doc.company) if doc.company else "" -%}
{%- set supplier_side = doc.card_direction in ["مستأجَرة من مورد", "إيجار من الباطن"] -%}
{%- set customer_side = doc.card_direction in ["مؤجَّرة لعميل", "إيجار من الباطن"] -%}
{#- the page direction follows the print language (frappe.utils.jinja_globals.is_rtl); stored Arabic option
    values are compared as stored and shown through _() (card/locale/en.po translates them) -#}
{#- right-to-left for ar/he/fa/ps and, in CARD, Urdu (card.print_utils.card_print_is_rtl, read at render time) -#}
{%- set dir = "rtl" if card_print_is_rtl() else "ltr" -%}
{%- set month_disp = frappe.utils.formatdate(doc.year ~ "-" ~ doc.month ~ "-01", "MMMM yyyy") if (doc.month and doc.year) else "" -%}
<div class="emc {{ dir }}" dir="{{ dir }}">
  {% if letter_head %}<div class="emc-lh">{{ letter_head }}</div>{% endif %}

  {% if company_name %}<div class="emc-co">{{ company_name|e }}</div>{% endif %}
  <div class="emc-title"><h2>{{ _("Equipment Monthly Operation Card") }}
    {%- if doc.docstatus == 0 %} <span class="st">{{ _("(Draft)") }}</span>{% elif doc.docstatus == 2 %} <span class="st">{{ _("(Cancelled)") }}</span>{% endif -%}
  </h2></div>

  <table class="emc-head-outer"><tr>
    <td class="ehc">
  <table class="emc-meta">
    <tr>
      <td class="ml">{{ _("Card no.") }}</td><td><span dir="ltr">{{ doc.name|e }}</span></td>
      <td class="ml">{{ _("Month") }}</td><td>{{ month_disp|e }}</td>
      <td class="ml">{{ _("Shift type") }}</td><td>{{ (_(doc.shift) if doc.shift else "")|e }}</td>
    </tr>
    <tr>
      <td class="ml">{{ _("Equipment name") }}</td><td>{{ (doc.equipment_name or '')|e }}{% if doc.equipment %} <span dir="ltr">({{ doc.equipment|e }})</span>{% endif %}</td>
      <td class="ml">{{ _("Equipment type") }}</td><td>{{ (eq_type or '')|e }}</td>
      <td class="ml">{{ _("Ownership") }}</td><td>{{ (_(doc.ownership) if doc.ownership else "")|e }}{% if doc.card_direction %} — {{ _(doc.card_direction)|e }}{% endif %}</td>
    </tr>
    <tr>
      <td class="ml">{{ _("Project name") }}</td><td>{{ (doc.project_name or doc.project or '')|e }}</td>
      <td class="ml">{{ _("Location") }}</td><td>{{ (doc.site_location or '')|e }}</td>
      <td class="ml">{{ _("Driver / Operator") }}</td><td>{{ (doc.operator_name or '')|e }}</td>
    </tr>
    <tr>
      {% if customer_side and not supplier_side %}
      <td class="ml">{{ _("Customer") }}</td><td>{{ (customer_name or doc.customer or '')|e }}</td>
      {% else %}
      <td class="ml">{{ _("Owner", context="Card Monthly Card") }}</td><td>{{ (supplier_name or doc.supplier or _("الشركة"))|e }}</td>
      {% endif %}
      <td class="ml">{{ _("Period") }}</td><td><span class="nw" dir="ltr">{{ frappe.utils.formatdate(doc.from_date) }} - {{ frappe.utils.formatdate(doc.to_date) }}</span></td>
      {% if supplier_side and customer_side %}
      <td class="ml">{{ _("Customer") }}</td><td>{{ (customer_name or doc.customer or '')|e }}</td>
      {% else %}
      <td class="ml"></td><td></td>
      {% endif %}
    </tr>
  </table>
    </td>
    {% if doc.image %}<td class="emc-img"><img src="{{ doc.image|e }}"></td>{% endif %}
  </tr></table>

  <table class="emc-days-wrap"><tr>
  {% for part in [days[:half], days[half:]] %}
    <td class="emc-half">
      <table class="emc-days">
        <tr>
          <th style="width:5%;">#</th>
          <th style="width:10%;">{{ _("Date") }}</th>
          <th style="width:13%;">{{ _("Day") }}</th>
          <th style="width:15%;">{{ _("Status") }}</th>
          <th style="width:11%;">{{ _("Hrs") }}</th>
          <th style="width:23%;">{{ _("Idle reason") }}</th>
          <th style="width:23%;">{{ _("Notes") }}</th>
        </tr>
        {% for r in part %}
          <tr class="{% if ((frappe.utils.getdate(r.operation_date).weekday() == 4) if r.operation_date else (r.day_name == 'الجمعة')) %}fri{% endif %} {% if r.day_status != 'عمل' %}off{% endif %}">
            <td class="c">{{ r.idx }}</td>
            <td class="c">{{ frappe.utils.formatdate(r.operation_date, 'dd-MM') }}</td>
            {#- the weekday is printed from the date, in the print language -#}
            <td>{{ (frappe.utils.formatdate(r.operation_date, 'EEE') if r.operation_date else (r.day_name or ''))|e }}</td>
            <td>{{ (_(r.day_status) if r.day_status else '')|e }}</td>
            <td class="num">{% if (r.working_hours or 0) > 0 %}{{ '%.1f'|format(r.working_hours) }}{% else %}-{% endif %}</td>
            <td class="t">{{ (r.idle_reason or '')|e }}</td>
            <td class="t">{{ (r.notes or '')|e }}</td>
          </tr>
        {% endfor %}
        {% if part|length < half %}
          <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
        {% endif %}
      </table>
    </td>
  {% endfor %}
  </tr></table>

  {#- settlement per billed side = the invoice of that side: gross (the base
      line) + that side's additions - its deductions = the net the PI/SI bills
      before VAT (posting._card_lines asserts the same identity). Supplier:
      amount -> net_amount; customer: customer_amount -> customer_net_amount.
      A row without a side is a v1.1 row, counted on the supplier side
      (backfill_adjustment_side). One weight per cell: Qt overlaps a
      regular+bold Arabic run pair. -#}
  {%- set adj = doc.adjustments or [] -%}
  {%- set ns = namespace(s_add=0, s_ded=0, s_n=0, c_add=0, c_ded=0, c_n=0) -%}
  {%- for a in adj -%}
    {%- set amt = frappe.utils.flt(a.amount) -%}
    {%- if a.side == "Customer" -%}
      {%- set ns.c_n = ns.c_n + 1 -%}
      {%- if a.adjustment_type == "إضافة" %}{% set ns.c_add = ns.c_add + amt %}{% elif a.adjustment_type == "خصم" %}{% set ns.c_ded = ns.c_ded + amt %}{% endif -%}
    {%- else -%}
      {%- set ns.s_n = ns.s_n + 1 -%}
      {%- if a.adjustment_type == "إضافة" %}{% set ns.s_add = ns.s_add + amt %}{% elif a.adjustment_type == "خصم" %}{% set ns.s_ded = ns.s_ded + amt %}{% endif -%}
    {%- endif -%}
  {%- endfor %}
  {#- three columns: the additions/deductions rows at the start side, the card totals, and the settlement
      of each billed side at the end side of the page (its net is the last, bold figure); without a
      settlement the card totals take the end column -#}
  {%- set settles = supplier_side or ns.s_n or customer_side or ns.c_n -%}
  {%- set totals_html -%}
  <table class="emc-tot emc-totals">
    <tr><th colspan="2">{{ _("Card totals") }}</th></tr>
    <tr><td class="k">{{ _("Total operating hours") }}</td><td class="v">{{ '%.1f'|format(doc.total_working_hours or 0) }}</td></tr>
    <tr><td class="k">{{ _("Working days") }}</td><td class="v">{{ doc.working_days or 0 }}</td></tr>
    {% if customer_side and not supplier_side %}
    <tr><td class="k">{{ _("Customer rate ({0})").format(_(doc.customer_rate_type) if doc.customer_rate_type else '')|e }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_rate or 0) }}</td></tr>
    <tr class="last"><td class="k">{{ _("Total amount") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</td></tr>
    {% elif supplier_side %}
    <tr><td class="k">{{ _("Rate ({0})").format(_(doc.rate_type) if doc.rate_type else '')|e }}</td><td class="v">{{ frappe.utils.fmt_money(doc.rate or 0) }}</td></tr>
    <tr{% if not customer_side %} class="last"{% endif %}><td class="k">{{ _("Total amount") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.amount or 0) }}</td></tr>
    {% if customer_side %}
    <tr><td class="k">{{ _("Customer rate ({0})").format(_(doc.customer_rate_type) if doc.customer_rate_type else '')|e }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_rate or 0) }}</td></tr>
    <tr class="last"><td class="k">{{ _("Customer side amount") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</td></tr>
    {% endif %}
    {% else %}
    <tr class="last"><td class="k">{{ _("Internal operation") }}</td><td class="v">{{ _("Not billed") }}</td></tr>
    {% endif %}
  </table>
  {%- endset %}
  <table class="emc-sum"><tr>
    <td class="emc-sum-s">
  {% if adj %}
  <div class="emc-cap">{{ _("Additions and deductions") }}</div>
  <table class="emc-adj">
    <tr>
      <th style="width:19%;">{{ _("Side") }}</th>
      <th style="width:19%;">{{ _("Type") }}</th>
      <th>{{ _("Description") }}</th>
      <th style="width:24%;">{{ _("Adjustment amount") }}</th>
    </tr>
    {% for a in adj %}
    <tr>
      <td class="c">{{ _("Customer") if a.side == "Customer" else _("Supplier") }}</td>
      <td class="c">{{ (_(a.adjustment_type) if a.adjustment_type else '')|e }}</td>
      <td>{{ (a.description or a.adjustment_type_ref or '')|e }}</td>
      <td class="num">{{ frappe.utils.fmt_money(a.amount or 0) }}</td>
    </tr>
    {% endfor %}
  </table>
  {% endif %}
    </td>
    <td class="emc-sum-g"></td>
    <td class="emc-sum-m">{% if settles %}{{ totals_html }}{% endif %}</td>
    <td class="emc-sum-g"></td>
    <td class="emc-sum-e">
  {%- if not settles %}{{ totals_html }}{% endif %}
  {% if supplier_side or ns.s_n %}
  <table class="emc-tot emc-net">
    <tr><th colspan="2">{{ _("Supplier settlement") }}</th></tr>
    <tr><td class="k">{{ _("Supplier gross") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.amount or 0) }}</td></tr>
    <tr><td class="k">{{ _("Supplier additions") }}</td><td class="v">{{ frappe.utils.fmt_money(ns.s_add) }}</td></tr>
    <tr><td class="k">{{ _("Supplier deductions") }}</td><td class="v">{{ frappe.utils.fmt_money(ns.s_ded) }}</td></tr>
    <tr class="last"><td class="k">{{ _("Supplier net before VAT") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.net_amount or 0) }}</td></tr>
  </table>
  {% endif %}
  {% if customer_side or ns.c_n %}
  <table class="emc-tot emc-net">
    <tr><th colspan="2">{{ _("Customer settlement") }}</th></tr>
    <tr><td class="k">{{ _("Customer gross") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</td></tr>
    <tr><td class="k">{{ _("Customer additions") }}</td><td class="v">{{ frappe.utils.fmt_money(ns.c_add) }}</td></tr>
    <tr><td class="k">{{ _("Customer deductions") }}</td><td class="v">{{ frappe.utils.fmt_money(ns.c_ded) }}</td></tr>
    <tr class="last"><td class="k">{{ _("Customer net before VAT") }}</td><td class="v">{{ frappe.utils.fmt_money(doc.customer_net_amount or 0) }}</td></tr>
  </table>
  {% endif %}
    </td>
  </tr></table>

  <table class="emc-sign"><tr>
    <td><div class="l"></div><div class="t">{{ _("Driver / operator signature") }}</div><div class="n">{% if doc.operator_name %}{{ doc.operator_name|e }}{% else %}&nbsp;{% endif %}</div></td>
    <td><div class="l"></div><div class="t">{{ _("Site supervisor approval") }}</div><div class="n">&nbsp;</div></td>
    <td><div class="l"></div><div class="t">{{ _("Project manager approval") }}</div><div class="n">&nbsp;</div></td>
  </tr></table>
</div>
